// Each damage entry is about one insured item, and no two entries may be about
// the same one: a policy covering a single sword cannot suffer two damaged
// swords. Entries are matched against the items still unaccounted for, so the
// MHPCO refuses both damages to what it did not insure and damages beyond the
// number of alike items it did.
const damagedItemsIn = (policy: Policy, incident: Incident): Item[] => {
  const unclaimed = [...policy.items];

  return incident.damages.map((damage) => {
    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
    const item = orRejected(
      index === -1 ? undefined : unclaimed[index],
      `damaged item is not insured by this policy: ${damage.itemType}`,
    );
    unclaimed.splice(index, 1);

    return item;
  });
};

const incidentPayoutOf = (incident: Incident, policy: Policy): number =>
  roundedDownInMHPCOsFavour(
    sumOf(
      damagedItemsIn(policy, incident).map((item, index) =>
        damagePayoutOf(incident.damages[index], item),
      ),
    ),
  );

